# find inode of socket listening on 5199
inodes=set()
for f in ('/proc/net/tcp','/proc/net/tcp6'):
    try:
        for line in open(f).read().splitlines()[1:]:
            p=line.split()
            local=p[1]; st=p[3]
            port=int(local.split(':')[1],16)
            if port==5199 and st=='0A':
                inodes.add(p[9])
    except FileNotFoundError: pass
print("inodes:",inodes)
for pid in filter(str.isdigit, os.listdir('/proc')):
    try:
        for fd in os.listdir(f'/proc/{pid}/fd'):
            try:
                link=os.readlink(f'/proc/{pid}/fd/{fd}')
            except OSError: continue
            if link.startswith('socket:[') and link[8:-1] in inodes:
                cmd=open(f'/proc/{pid}/cmdline','rb').read().replace(b'\0',b' ').decode()[:160]
                print(pid, cmd)
                break
    except (FileNotFoundError,PermissionError): pass
EOF

node -e '
const fs=require("fs");
const inodes=new Set();
for (const f of ["/proc/net/tcp","/proc/net/tcp6"]) {
  try {
    const lines=fs.readFileSync(f,"utf8").split("\n").slice(1);
    for (const l of lines) {
      const p=l.trim().split(/\s+/);
      if (p.length<10) continue;
      const port=parseInt(p[1].split(":")[1],16);
      if (port===5199 && p[3]==="0A") inodes.add(p[9]);
    }
  } catch {}
}
console.log("inodes:",[...inodes]);
for (const pid of fs.readdirSync("/proc").filter(x=>/^\d+$/.test(x))) {
  let fds; try { fds=fs.readdirSync(`/proc/${pid}/fd`); } catch { continue; }
  for (const fd of fds) {
    let link; try { link=fs.readlinkSync(`/proc/${pid}/fd/${fd}`); } catch { continue; }
    const m=link.match(/^socket:\[(\d+)\]$/);
    if (m && inodes.has(m[1])) {
      const cmd=fs.readFileSync(`/proc/${pid}/cmdline`,"utf8").replace(/\0/g," ").slice(0,160);
      console.log(pid, cmd);
      break;
    }
  }
}'

